function validate([s]) {
  if (typeof s !== 'string') return 's must be a string.';
  if (s.length > 200) return 's has at most 200 characters.';
  if (!/^[A-Za-z0-9 +\-.]*$/.test(s)) return 's may contain only letters, digits, spaces, +, - and dots.';
  return null;
}

