function myAtoi(s) {
  const MAX = 2 ** 31 - 1;
  const MIN = -(2 ** 31);
  let i = 0;
  while (i < s.length && s[i] === ' ') {
    i++;
  }
  let sign = 1;
  if (s[i] === '+' || s[i] === '-') {
    sign = s[i] === '-' ? -1 : 1;
    i++;
  }
  let result = 0;
  while (i < s.length && s[i] >= '0' && s[i] <= '9') {
    const digit = s.charCodeAt(i) - 48;
    result = result * 10 + sign * digit;
    if (result > MAX) {
      return MAX;
    }
    if (result < MIN) {
      return MIN;
    }
    i++;
  }
  return result;
}

