function myAtoi(s) {
  const match = /^ *([+-]?)([0-9]*)/.exec(s);
  if (match[2].length === 0) return 0;
  const value = BigInt(match[1] + match[2]);
  if (value > 2147483647n) return 2147483647;
  if (value < -2147483648n) return -2147483648;
  return Number(value);
}

