function generate(rand, size) {
  const large = size === 'large';
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const pick = (text) => text[Math.floor(rand() * text.length)];
  const all = 'abzABZ0123456789 +-.';
  if (rand() < 0.15) {
    let s = '';
    const n = int(0, large ? 200 : 12);
    for (let k = 0; k < n; k++) s += pick(all);
    return [s];
  }
  let s = ' '.repeat(int(0, large ? 80 : 3));
  const r = rand();
  if (r < 0.3) s += '-';
  else if (r < 0.5) s += '+';
  else if (r < 0.65) s += ['+-', '-+', '--', '.', 'a', ' x'][int(0, 5)];
  s += '0'.repeat(int(0, large ? 80 : 3));
  if (rand() < 0.2) s += ['2147483647', '2147483648', '2147483646', '2147483649', '99999999999'][int(0, 4)];
  else {
    const digits = int(0, large ? 30 : 12);
    for (let k = 0; k < digits; k++) s += pick('0123456789');
  }
  const tail = int(0, large ? 60 : 4);
  for (let k = 0; k < tail; k++) s += pick(all);
  return [s.slice(0, 200)];
}
